23. /** Zeebe JobHandler that invokes a Spring bean */
24. public class JobHandlerInvokingSpringBeans implements JobHandler {
25. 
26.   private static final Logger LOG = Loggers.JOB_WORKER_LOGGER;
27.   private final ZeebeWorkerValue workerValue;
28.   private final CommandExceptionHandlingStrategy commandExceptionHandlingStrategy;
29.   private final JsonMapper jsonMapper;
30.   private final MetricsRecorder metricsRecorder;
31. 
32.   public JobHandlerInvokingSpringBeans(
33.       ZeebeWorkerValue workerValue,
34.       CommandExceptionHandlingStrategy commandExceptionHandlingStrategy,
35.       JsonMapper jsonMapper,
36.       MetricsRecorder metricsRecorder) {
37.     this.workerValue = workerValue;
38.     this.commandExceptionHandlingStrategy = commandExceptionHandlingStrategy;
39.     this.jsonMapper = jsonMapper;
40.     this.metricsRecorder = metricsRecorder;
41.   }
42. 
43.   @Override
44.   public void handle(JobClient jobClient, ActivatedJob job) throws Exception {
45.     // TODO: Figuring out parameters and assignments could probably also done only once in the
46.     // beginning to save some computing time on each invocation
47.     List<Object> args =
48.         createParameters(jobClient, job, workerValue.getMethodInfo().getParameters());
49.     LOG.trace("Handle {} and invoke worker {}", job, workerValue);
50.     try {
51.       metricsRecorder.increase(
52.           MetricsRecorder.METRIC_NAME_JOB, MetricsRecorder.ACTION_ACTIVATED, job.getType());
53.       Object result = null;
54.       try {
55.         result = workerValue.getMethodInfo().invoke(args.toArray());
56.       } catch (Throwable t) {
57.         metricsRecorder.increase(
58.             MetricsRecorder.METRIC_NAME_JOB, MetricsRecorder.ACTION_FAILED, job.getType());
59.         // normal exceptions are handled by JobRunnableFactory
60.         // (https://github.com/camunda-cloud/zeebe/blob/develop/clients/java/src/main/java/io/camunda/zeebe/client/impl/worker/JobRunnableFactory.java#L45)
61.         // which leads to retrying
62.         throw t;
63.       }
64. 
65.       if (workerValue.getAutoComplete()) {
66.         LOG.trace("Auto completing {}", job);
67.         // TODO: We should probably move the metrics recording to the callback of a successful
68.         // command execution to avoid wrong counts
69.         metricsRecorder.increase(
70.             MetricsRecorder.METRIC_NAME_JOB, MetricsRecorder.ACTION_COMPLETED, job.getType());
71.         CommandWrapper command =
72.             new CommandWrapper(
73.                 createCompleteCommand(jobClient, job, result),
74.                 job,
75.                 commandExceptionHandlingStrategy);
76.         command.executeAsync();
77.       }
78.     } catch (ZeebeBpmnError bpmnError) {
79.       LOG.trace("Catched BPMN error on {}", job);
80.       // TODO: We should probably move the metrics recording to the callback of a successful command
81.       // execution to avoid wrong counts
82.       metricsRecorder.increase(
83.           MetricsRecorder.METRIC_NAME_JOB, MetricsRecorder.ACTION_BPMN_ERROR, job.getType());
84.       CommandWrapper command =
85.           new CommandWrapper(
86.               createThrowErrorCommand(jobClient, job, bpmnError),
87.               job,
88.               commandExceptionHandlingStrategy);
89.       command.executeAsync();
90.     }
91.   }
92. 
93.   private List<Object> createParameters(
94.       JobClient jobClient, ActivatedJob job, List<ParameterInfo> parameters) {
95.     List<Object> args = new ArrayList<>();
96.     for (ParameterInfo param : parameters) {
97.       Object arg = null; // parameter default null
98.       Class<?> clazz = param.getParameterInfo().getType();
99. 
100.       if (JobClient.class.isAssignableFrom(clazz)) {
101.         arg = jobClient;
102.       } else if (ActivatedJob.class.isAssignableFrom(clazz)) {
103.         arg = job;
104.       } else if (param.getParameterInfo().isAnnotationPresent(Variable.class)
105.           || param.getParameterInfo().isAnnotationPresent(ZeebeVariable.class)) {
106.         String paramName = getVariableName(param);
107.         Object variableValue = job.getVariablesAsMap().get(paramName);
108.         try {
109.           arg = mapZeebeVariable(variableValue, param.getParameterInfo().getType());
110.         } catch (ClassCastException | IllegalArgumentException ex) {
111.           throw new RuntimeException(
112.               "Cannot assign process variable '"
113.                   + paramName
114.                   + "' to parameter when executing job '"
115.                   + job.getType()
116.                   + "', invalid type found: "
117.                   + ex.getMessage());
118.         }
119.       } else if (param.getParameterInfo().isAnnotationPresent(VariablesAsType.class)
120.           || param.getParameterInfo().isAnnotationPresent(ZeebeVariablesAsType.class)) {
121.         try {
122.           arg = job.getVariablesAsType(clazz);
123.         } catch (RuntimeException e) {
124.           throw new RuntimeException(
125.               "Cannot assign process variables to type '"
126.                   + clazz.getName()
127.                   + "' when executing job '"
128.                   + job.getType()
129.                   + "', cause is: "
130.                   + e.getMessage(),
131.               e);
132.         }
133.       } else if (param.getParameterInfo().isAnnotationPresent(CustomHeaders.class)
134.           || param.getParameterInfo().isAnnotationPresent(ZeebeCustomHeaders.class)) {
135.         try {
136.           arg = job.getCustomHeaders();
137.         } catch (RuntimeException e) {
138.           throw new RuntimeException(
139.               "Cannot assign headers '"
140.                   + param.getParameterName()
141.                   + "' to parameter when executing job '"
142.                   + job.getType()
143.                   + "', cause is: "
144.                   + e.getMessage(),
145.               e);
146.         }
147.       }
148.       args.add(arg);
149.     }
150.     return args;
151.   }
152. 
153.   private String getVariableName(ParameterInfo param) {
154.     if (param.getParameterInfo().isAnnotationPresent(Variable.class)) {
155.       String nameFromAnnotation = param.getParameterInfo().getAnnotation(Variable.class).name();
156.       if (!Objects.equals(nameFromAnnotation, Variable.DEFAULT_NAME)) {
157.         LOG.trace("Extracting name {} from Variable.name", nameFromAnnotation);
158.         return nameFromAnnotation;
159.       }
160.       String valueFromAnnotation = param.getParameterInfo().getAnnotation(Variable.class).value();
161.       if (!Objects.equals(valueFromAnnotation, Variable.DEFAULT_NAME)) {
162.         LOG.trace("Extracting name {} from Variable.value", valueFromAnnotation);
163.         return valueFromAnnotation;
164.       }
165.     }
166.     LOG.trace("Extracting variable name from parameter name");
167.     return param.getParameterName();
168.   }
169. 
170.   public static FinalCommandStep createCompleteCommand(
171.       JobClient jobClient, ActivatedJob job, Object result) {
172.     CompleteJobCommandStep1 completeCommand = jobClient.newCompleteCommand(job.getKey());
173.     if (result != null) {
174.       if (result.getClass().isAssignableFrom(Map.class)) {
175.         completeCommand = completeCommand.variables((Map) result);
176.       } else if (result.getClass().isAssignableFrom(String.class)) {
177.         completeCommand = completeCommand.variables((String) result);
178.       } else if (result.getClass().isAssignableFrom(InputStream.class)) {
179.         completeCommand = completeCommand.variables((InputStream) result);
180.       } else {
181.         completeCommand = completeCommand.variables(result);
182.       }
183.     }
184.     return completeCommand;
185.   }
186. 
187.   private FinalCommandStep<Void> createThrowErrorCommand(
188.       JobClient jobClient, ActivatedJob job, ZeebeBpmnError bpmnError) {
189.     ThrowErrorCommandStep2 command =
190.         jobClient
191.             .newThrowErrorCommand(job.getKey()) // TODO: PR for taking a job only in command chain
192.             .errorCode(bpmnError.getErrorCode())
193.             .errorMessage(bpmnError.getErrorMessage());
194.     if (bpmnError.getVariables() != null) {
195.       command.variables(bpmnError.getVariables());
196.     }
197.     return command;
198.   }
199. 
200.   private <T> T mapZeebeVariable(Object toMap, Class<T> clazz) {
201.     if (toMap != null && !clazz.isInstance(toMap)) {
202.       //      if (jsonMapper != null) {
203.       return jsonMapper.fromJson(jsonMapper.toJson(toMap), clazz);
204.       //      }
205.       //      return DEFAULT_OBJECT_MAPPER.convertValue(toMap, clazz);
206.     } else {
207.       return clazz.cast(toMap);
208.     }
209.   }
210. }
